```cpp
void bubble(RandomIter begin, RandomIter end, Comparator comp = Comparator{}) {
    using difference_type = typename std::iterator_traits<RandomIter>::difference_type;
    difference_type n = std::distance(begin, end);
    if (n == 0) return;

    for (difference_type i = 0; i < n - 1; ++i) {
        bool swapped = false;
        // With each pass, the largest element is bubbled to the end.
        // The last i elements are already sorted, so exclude them.
        for (RandomIter current = begin; current < end - 1 - i; ++current) {
            RandomIter next = current + 1;
            if (comp(*next, *current)) {
