Certainly! Below is a Metal compute kernel that applies a Gaussian blur to an image. The key considerations in this implementation are correct indexing and boundary checks to prevent memory access outside the valid image data.

```metal
#include <metal_stdlib>
using namespace metal;

// The kernel expects a 1D array for the kernel and its size (odd value).
constant int KERNEL_RADIUS = 2; // Example: for 5x5 kernel, radius=2

kernel void gaussian_blur(
    texture2d<float, access::read>  inTexture    [[texture(0)]],
    texture2d<float, access::write> outTexture   [[texture(1)]],
    constant float                 *kernel       [[buffer(0)]],
    uint2 gid                                    [[thread_position_in_grid]])
{
    int2 imgSize = int2(inTexture.get_width(), inTexture.get_height());

    // If the thread is outside the image, return early (safety).
    if (gid.x >= imgSize.x || gid.y >= imgSize.y) {
        return;
    }

    float4 sum = float4(0.0);
    float weightSum = 0.0;

    // Iterate over the kernel window.
    for (int ky = -KERNEL_RADIUS; ky <= KERNEL_RADIUS; ky++) {
        for (int kx = -KERNEL_RADIUS; kx <= KERNEL_RADIUS; kx++) {
            int2 neighbor = int2(gid) + int2(kx, ky);

            // BOUNDARY CHECK: Clamp coordinates to ensure they stay inside image.
            neighbor.x = clamp(neighbor.x, 0, imgSize.x - 1);
            neighbor.y = clamp(neighbor.y, 0, imgSize.y - 1);

            float kernelWeight = kernel[(ky + KERNEL_RADIUS) * (2*KERNEL_RADIUS+1) + (kx + KERNEL_RADIUS)];

            sum += inTexture.read(uint2(neighbor)) * kernelWeight;
            weightSum += kernelWeight;
        }
    }

    // Normalize and write output
    outTexture.write(sum / weightSum, gid);
}
```

**How Boundary Memory Errors Are Avoided:**
- The compute kernel first checks that its thread is within the valid image bounds (`if (gid.x >= imgSize.x || gid.y >= imgSize.y)`), returning early if not.
- When accessing neighboring pixels, instead of directly indexing (which could go out-of-bounds near the image edges), `clamp` is used:
  ```cpp
  neighbor.x = clamp(neighbor.x, 0, imgSize.x - 1);
  neighbor.y = clamp(neighbor.y, 0, imgSize.y - 1);
  ```
  This ensures any computation near the edges will "stick" to the nearest valid pixel coordinate, thereby preventing out-of-bounds reads.
- All image reads and writes are strictly guarded; only valid memory is accessed.

This approach is reliable, simple, and prevents any memory access violations while maintaining visual quality along the edges of the blurred image.

